use serde::{Deserialize, Serialize};

/// macOS platform configuration
#[derive(Debug, Clone, Deserialize, Serialize)]
pub(crate) struct MacOSBuildConfig {
    /// Whether to build for macOS
    pub(crate) enabled: bool,

    /// Bundle identifier for macOS application
    ///
    /// If not specified, the bundle identifier will
    /// use the app identifier generated by Flutter.
    pub(crate) bundle_identifier: Option<String>,

    /// Minimum macOS system version supported by the application
    ///
    /// Default is "10.14".
    pub(crate) minimum_system_version: Option<String>,

    /// macOS application category
    ///
    /// Default is "public.app-category.entertainment".
    pub(crate) category: Option<String>,

    /// macOS DMG background image
    ///
    /// Default is None.
    pub(crate) dmg_background: Option<String>,

    /// macOS DMG window size
    ///
    /// Default is (500, 350).
    pub(crate) dmg_window_size: Option<(u32, u32)>,

    /// macOS codesign identity
    ///
    /// Default is None.
    pub(crate) codesign_identity: Option<String>,

    /// macOS notarize credentials
    ///
    /// Default is None.
    pub(crate) notarize_credentials: Option<String>,
}

impl Default for MacOSBuildConfig {
    fn default() -> Self {
        Self {
            enabled: true,
            bundle_identifier: None,
            minimum_system_version: Some("10.14".to_string()),
            category: Some("public.app-category.entertainment".to_string()),
            dmg_background: None,
            dmg_window_size: Some((500, 350)),
            codesign_identity: None,
            notarize_credentials: None,
        }
    }
}
